WITH filtered_suppliers AS (SELECT * FROM suppliers WHERE city <> 'London'), suppliers_stats AS (SELECT CASE WHEN rating >= 3.4 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END AS rating_bucket, MIN(rating) AS min_rating FROM filtered_suppliers GROUP BY CASE WHEN rating >= 3.4 THEN 'high' WHEN rating >= 2.1 THEN 'mid' ELSE 'low' END) SELECT rating_bucket, min_rating FROM suppliers_stats ORDER BY rating_bucket DESC, min_rating DESC
